    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideDispute>>, TError,DecideDisputeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof decideDispute>>, TError,DecideDisputeMutationVariables, TContext> => {

const mutationKey = getDecideDisputeMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof decideDispute>>, DecideDisputeMutationVariables> = (props) => {
          const {disputeId,data} = props ?? {};

          return  decideDispute(disputeId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type DecideDisputeMutationResult = NonNullable<Awaited<ReturnType<typeof decideDispute>>>
    export type DecideDisputeMutationBody = BodyType<DisputeDecisionInput>
    export type DecideDisputeMutationError = ErrorType<unknown>
    export type DecideDisputeMutationVariables = {disputeId: number;data: BodyType<DisputeDecisionInput>}

    /**
 * @summary Make a simulated financial dispute decision
 */
export const useDecideDispute = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof decideDispute>>, TError,DecideDisputeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof decideDispute>>,
        TError,
        DecideDisputeMutationVariables,
        TContext
      > => {
      return useMutation(getDecideDisputeMutationOptions(options), queryClient);
    }

